 \label{thm:lowerbound}
For $x_0 \in (0,1)^d$, let $\mathcal{P}$ denote the model where:
\begin{enumerate}
\item $f(x)$ is bounded above by a constant, 
\item $\pi(x)$ is $\alpha$-smooth, 
\item $\mu_0(x)$ is $\beta$-smooth, and
\item $\tau(x)$ is $\gamma$-smooth.
\end{enumerate}
Let $s \equiv (\alpha+\beta)/2$. 
Then for $n$ larger than a constant depending on $(\alpha,\beta,\gamma,d)$, the minimax rate is lower bounded as
\begin{align*}
\inf_{\widehat\tau} \sup_{P \in \mathcal{P}} \mathbb{E}_P | \widehat\tau(x_0) - \tau_P(x_0)| \gtrsim \begin{cases}
n^{-1/\left(1 + \frac{d}{2\gamma} + \frac{d}{4s} \right) } & \text{ if } s < \frac{d/4}{1+d/2\gamma}  \\
n^{-1/\left(2 + \frac{d}{\gamma}  \right) } & \text{ otherwise}  . 
\end{cases}
\end{align*}

\begin{align*}
\inf_{\widehat\tau} \sup_{P \in \mathcal{P}} \mathbb{E}_P | \widehat\tau(x_0) - \tau_P(x_0)| \gtrsim \begin{cases}
n^{-1/\left(1 + \frac{d}{2\gamma} + \frac{d}{4s} \right) } & \text{ if } s < \frac{d/4}{1+d/2\gamma}  \\
n^{-1/\left(2 + \frac{d}{\gamma}  \right) } & \text{ otherwise}  . 
\end{cases}
\end{align*}

  \label{def:construction}
Let:
\begin{enumerate}
\item $B: \mathbb{R}^d \rightarrow \mathbb{R}$ denote a $C^\infty$ function with $B(x)=1$ for $x \in [-1/4, 1/4]^d$, and $B(x)=0$ for $x \notin [-1/2,1/2]^d$,
\item $\mathcal{C}_h(x_0)$ denote the cube centered at $x_0 \in (0,1)^d$ with sides of length $h \leq 1/4$, 
\item $(\mathcal{X}_1,\dots,\mathcal{X}_k)$ denote a partition of $\mathcal{C}_h(x_0)$ into $k$ cubes of equal size (for $k$ an integer raised to the power $d$), with midpoints $(m_1,\dots,m_k)$, so each cube $\mathcal{X}_j = \mathcal{C}_{h/k^{1/d}}(m_j)$ has side length $h/k^{1/d}$.
\end{enumerate}
Then for $\lambda_j \in \{-1,1\}$ define the functions
\begin{align*}
\tau_h(x) &= h^\gamma B\left( \frac{x-x_0}{2h} \right)  \\
\mu_{0\lambda}(x) &= \frac{1}{2} +  \left( h/k^{1/d} \right)^{\beta} \sum_{j=1}^k \lambda_j B \left( \frac{x-m_j}{h/k^{1/d}}  \right) \\
\pi_\lambda(x) &=   \frac{1}{2} +   \left(  h/k^{1/d} \right)^{\alpha} \sum_{j=1}^k \lambda_j B \left( \frac{x-m_j}{h/k^{1/d}}  \right) \\
 f(x) &= \mathbbold{1}(x \in \mathcal{S}_{hk}) \Big/ \left\{ 1  - \left( \frac{4^d - 1}{2^d} \right) h^d \right\}
\end{align*}
where $\mathcal{S}_{hk} = \left\{ \bigcup_{j=1}^k \mathcal{C}_{h/2k^{1/d}}(m_j) \right\} \bigcup \left\{ [0,1]^d \setminus \mathcal{C}_{2h}(x_0) \right\}$. 
Finally let the distributions $P_\lambda$ and $Q_\lambda$ be defined via the densities
\begin{align*}
p_\lambda &= (f,1/2, \mu_{0\lambda}-\tau_h/2,\tau_h) \\
q_\lambda &= (f,\pi_\lambda,\mu_{0\lambda},0) . 
\end{align*}

