| \mathbb{E}(\widehat{S}_j - S_j \mid D^n) | & \ \lesssim \ \left( h/k^{1/d} \right)^{2s}  + h^\gamma  \left( h/k^{1/d} \right)^{\alpha} \\
& \hspace{.5in} + \Big( h^\gamma +\| \widehat\mu_0 - \mu_0 \|_{F^*} \Big) \left( \| \widehat\pi - \pi \|_{F^*}   \| \widehat\Omega^{-1}-\Omega^{-1} \|    \right) .
\end{align*}

\begin{align*}
| \mathbb{E}(\widehat{S}_j - S_j \mid D^n) | & \ \lesssim \ \left( h/k^{1/d} \right)^{2s}  + h^\gamma  \left( h/k^{1/d} \right)^{\alpha} \\
& \hspace{.5in} + \Big( h^\gamma +\| \widehat\mu_0 - \mu_0 \|_{F^*} \Big) \left( \| \widehat\pi - \pi \|_{F^*}   \| \widehat\Omega^{-1}-\Omega^{-1} \|    \right) .
\end{align*}

By iterated expectation, the conditional mean of the first-order term in $\widehat{R}$,  i.e., the quantity $\mathbb{E}\{ \rho_h(X_1)  K_h(X_1) \widehat\varphi_{y1}(Z) \mid D^n \} $ is equal to
\begin{align} 
 R& + \int  \rho_h(x) K_h(x)  \{ \pi(x) - \widehat\pi(x) \}\{ \pi(x) \tau(x) + \mu_0(x) - \widehat\mu_0(x) \}  \ dF(x) \nonumber \\
& = R + \int \rho(v) \{ \pi^*(v) - \widehat\pi^*(v) \}\{ \pi^*(v) \tau^*(v) +  \mu_0^*(v) - \widehat\mu_0^*(v) \}  \ dF^*(v) \nonumber
\end{align}
where we use the change of variable $v = \frac{1}{2} + \frac{x-x_0}{h}$ and again define for any function $g: \mathbb{R}^d \mapsto \mathbb{R}$ its corresponding stretched version as $g^*(v) = g(x_0 + h(v-1/2))$. To ease notation it is left implicit that any integral over $v$ is only over $\{v : \|v-1/2\| \leq 1/2 \}$.  Similarly for $\widehat{Q}$ we have that $\mathbb{E}\{ \rho_h(X_1)  K_h(X_1) \widehat\varphi_{a1}(Z) \rho_h(X_1)^{ \mathrm{\scriptscriptstyle T} } \mid D^n \} $ equals
\begin{align} 

 Q &+ \int  \rho_h(x) K_h(x)  \{ \pi(x) - \widehat\pi(x) \} \pi(x) \rho_h(x)^{ \mathrm{\scriptscriptstyle T} } \ dF(x) \nonumber \\
& = Q + \int \rho(v) \{ \pi^*(v) - \widehat\pi^*(v) \} \pi^*(v) \rho(v) \ dF^*(v) \nonumber
\end{align}
so that for the first-order term in $\widehat{S}$ (denoted $\widehat{R}_1-\widehat{Q}_1 \theta$ in discussion of the moment condition \eqref{eq:moment}) we have
\begin{align}
\mathbb{E}\{ \rho_h(X_1)  &K_h(X_1)  \widehat\varphi_{y1}(Z) \mid D^n \} - \mathbb{E}\{ \rho_h(X_1)  K_h(X_1) \widehat\varphi_{a1}(Z) \rho_h(X_1) \mid D^n \} \theta  \nonumber\\
&= R-Q\theta +  \int \rho(v) \{ \pi^*(v) - \widehat\pi^*(v) \}\{  \mu_0^*(v) - \widehat\mu_0^*(v) \}  \ dF^*(v) \nonumber \\
& \hspace{.5in} + \int \rho(v)\pi^*(v)  \{ \pi^*(v) - \widehat\pi^*(v) \} \{ \tau^*(v) - \tau_h^*(v) \}  \ dF^*(v) . \label{eq:firstbias}
\end{align}
The conditional mean of the second-order influence function term in $\widehat{R}$ is
\begin{align}
&\mathbb{E}\{   \rho_h(X_1) K_h(X_1) \widehat\varphi_{y2}(Z_1,Z_2)K_h(X_2) \mid D^n \} \label{eq:r2ndorder} \\


&= - \int \rho(v_1)\{\pi^*(v_1) - \widehat\pi^*(v_1)\} \widehat\Pi_{b}(\pi^* \tau^* + \mu_0^*-\widehat\mu_0^*)(v_1) \ dF^*(v_1) \nonumber
\end{align}
where we define
\begin{align*}
\Pi_{b}g^*(u) &= b(u)^{ \mathrm{\scriptscriptstyle T} } \Omega^{-1} \int {b}(v) g^*(v) \ dF^*(v) 
\end{align*}
as the $F^*$-weighted linear projection of $g^*$ on the basis $b$, and $\widehat\Pi_{b} g^*(u)$ as the estimated version, which simply replaces $\Omega$ with $\widehat\Omega$. Similarly for $\widehat{Q}\theta$ we have
\begin{align}
&\mathbb{E}\{   \rho_h(X_1) K_h(X_1) \widehat\varphi_{a2}(Z_1,Z_2)K_h(X_2) \rho_h(X_2)^{ \mathrm{\scriptscriptstyle T} } \theta \mid D^n \} \label{eq:q2ndorder}  \\


&= - \int \rho(v_1) \{ \pi^*(v_1) - \widehat\pi^*(v_1) \} \widehat\Pi_{b}(\pi^* \tau_h^*)(v_1) \ dF^*(v_1)  \nonumber
\end{align}
so that the conditional mean \eqref{eq:r2ndorder} minus the  conditional mean \eqref{eq:q2ndorder} equals
\begin{align}

 - \int \rho(v_1)\{\pi^*(v_1) - \widehat\pi^*(v_1)\} \widehat\Pi_{b}\{ \pi^* ( \tau^* - \tau_h^* ) + (\mu_0^*-\widehat\mu_0^*)\}(v_1) \ dF^*(v_1) . \label{eq:secondbias}
\end{align}
Therefore adding the first- and second-order expected values in \eqref{eq:firstbias} and \eqref{eq:secondbias},  the overall bias relative to $S$ is
\begin{align}
&\int  \rho(v)  \{ \pi^*(v) - \widehat\pi^*(v)\}  (I-\widehat\Pi_{b}) \{ \pi^* ( \tau^* - \tau_h^* ) + (\mu_0^*-\widehat\mu_0^*)\}(v) \ dF^*(v) \nonumber \\


&= \int (I-\Pi_b) \{ \rho (\pi^* - \widehat\pi^*)\}(v) (I-\Pi_{b})\{ \pi^* ( \tau^* - \tau_h^* ) + (\mu_0^*-\widehat\mu_0^*)\}(v) \ dF^*(v) \label{eq:mainbias}  \\
& \hspace{.2in} + \int \rho(v) \{ \pi^*(v) - \widehat\pi^*(v)\} (\Pi_{b}-\widehat\Pi_{b})\{ \pi^* ( \tau^* - \tau_h^* ) + (\mu_0^*-\widehat\mu_0^*)\}(v) \ dF^*(v)  \label{eq:covbias} 
\end{align}
by the orthogonality of a projection with its residuals (Lemma \ref{lem:projections}(i)). \\

Now we analyze the bias terms \eqref{eq:mainbias} and \eqref{eq:covbias} separately; the first is the main bias term, which would arise even if the covariate density were known, and the second is the contribution coming from having to estimate the covariate density. \\

Crucially, by virtue of using the localized basis $b_{hk}$, the projections in these bias terms are of stretched versions of the nuisance functions $(\pi^*-\widehat\pi^*)$ and $(\mu_0^*-\widehat\mu_0^*)$, on the standard  \emph{non-localized} basis $b$, with weights equal to the stretched density $dF^*$. This is important because stretching a function increases its smoothness; in particular, the stretched and scaled function $g^*(v)/h^\alpha$ is $\alpha$-smooth whenever $g$ is $\alpha$-smooth. This follows since  $| D^{\lfloor \alpha \rfloor} g^*(v) - D^{\lfloor \alpha \rfloor} g^*(v') |$ equals
\begin{align*}

&\left| D^{\lfloor \alpha \rfloor} g( x_0 + h(v-1/2) ) - D^{\lfloor \alpha \rfloor} g( x_0 + h(v'-1/2) ) \right|  \\
&\hspace{.4in}= h^{\lfloor \alpha \rfloor} \left| g^{(\lfloor \alpha \rfloor)}( x_0 + h(v-1/2) )  - g^{(\lfloor \alpha \rfloor)}( x_0 + h(v'-1/2) )  \right| \\
&\hspace{.4in}\lesssim h^\alpha | v - v'| 
\end{align*}
where the second equality follows by the chain rule, and the third since $g$ is $\alpha$-smooth. Thus the above  implies 
$ h^{-\alpha} \left| D^{\lfloor \alpha \rfloor} g^*(v) - D^{\lfloor \alpha \rfloor} g^*(v') \right| \lesssim  | v - v'| ,  $
i.e., that $g^*(v)/h^\alpha$ is $\alpha$-smooth. \\

Therefore if $g$ is $\alpha$-smooth, then 
$\| (I - \Pi_b) g^*/h^\alpha \|_{F^*} \lesssim k^{-\alpha/d}$
by the \text{H\"{o}lder}{} approximation properties \eqref{eq:holder} of the basis $b$, and so it follows that
\begin{equation}
\| (I - \Pi_b) g^* \|_{F^*} \ \lesssim \ h^\alpha k^{-\alpha/d} = \left(h/k^{1/d} \right)^{\alpha} \label{eq:smallbias}
\end{equation}
for any $\alpha$-smooth function $g$. \\


